<script setup lang="ts">
import { onLoad } from '@dcloudio/uni-app'
import { reactive, ref } from 'vue'
import { API_ORIGIN } from '../../api/client'
import { createProperty, updateProperty, type Property } from '../../api/properties'
const id = ref(''); const form = reactive<Partial<Property>>({ title:'', community:'', location:'', layout:'', rentMonthly:0, feeText:'直租无中介费', description:'', ownerId:'xiaopi-admin' }); const roomCount = ref('一室'); const hallCount = ref('一厅'); const rentType = ref('整租'); const roomType = ref('单间'); const toiletType = ref('独卫'); const bayWindow = ref('带飘窗'); const amenities = ref(['冰箱','洗衣机','空调','热水器']); const amenityOptions = ['冰箱','洗衣机','空调','热水器','电视','宽带','燃气','油烟机','沙发','衣柜','书桌','床']; const images = ref<string[]>([]); const videos = ref<string[]>([]); const saving = ref(false)
onLoad((query) => { id.value = String(query?.id || '') })
const syncLayout = () => { form.layout = `${roomCount.value}${hallCount.value} · ${rentType.value} · ${roomType.value} · ${toiletType.value} · ${bayWindow.value}` }
const pick = (type: 'image'|'video') => uni.chooseMedia({ count:type==='image'?9:1, mediaType:[type], sourceType:['album','camera'], maxDuration:60, sizeType:['compressed'], success:(res) => { const paths=res.tempFiles.map((x:any)=>x.tempFilePath); type==='image'?images.value.push(...paths):videos.value.push(...paths) } })
const upload = (path:string, type:string, propertyId:string) => new Promise((resolve,reject)=>uni.uploadFile({url:`${API_ORIGIN}/api/v1/media/upload`,filePath:path,name:'file',formData:{propertyId,mediaType:type},success:resolve,fail:reject}))
const save = async () => { if(!form.community||!form.rentMonthly)return uni.showToast({title:'请填写小区和租金',icon:'none'}); saving.value=true; try { const details = String(form.description || '').replace(/^配套设施：[^\n]*\n?/, ''); const payload = {...form, description:`配套设施：${amenities.value.join('、')}\n${details}`.trim()}; const p=id.value?await updateProperty({...payload,id:id.value}):await createProperty(payload); id.value=p.id; for(const path of images.value)await upload(path,'image',p.id); for(const path of videos.value)await upload(path,'video',p.id); uni.showToast({title:'房源已保存'}); images.value=[]; videos.value=[] } finally { saving.value=false } }
</script>
<template><view class="page"><view class="hint card">管理员录入正式房源。请先完成实地核验，再上传真实图文和视频素材。</view><view class="card"><view class="field"><text>房源标题</text><input v-model="form.title" placeholder="例如：采光好的一居室" /></view><view class="field"><text>小区</text><input v-model="form.community" placeholder="请输入小区名称" /></view><view class="field"><text>位置</text><input v-model="form.location" placeholder="区域 / 地铁 / 商圈" /></view><view class="section-title">房源属性</view><view class="picker-grid"><picker :range="['一室','两室','三室','四室','五室及以上']" @change="roomCount=$event.detail.value===0?'一室':(['一室','两室','三室','四室','五室及以上'][$event.detail.value]);syncLayout()"><view class="picker-item">{{ roomCount }}<small>卧室</small></view></picker><picker :range="['一厅','两厅','三厅','无厅']" @change="hallCount=['一厅','两厅','三厅','无厅'][$event.detail.value];syncLayout()"><view class="picker-item">{{ hallCount }}<small>厅</small></view></picker><picker :range="['整租','合租']" @change="rentType=['整租','合租'][$event.detail.value];syncLayout()"><view class="picker-item">{{ rentType }}<small>方式</small></view></picker><picker :range="['单间','主卧','次卧','床位']" @change="roomType=['单间','主卧','次卧','床位'][$event.detail.value];syncLayout()"><view class="picker-item">{{ roomType }}<small>房间</small></view></picker><picker :range="['独卫','非独卫']" @change="toiletType=['独卫','非独卫'][$event.detail.value];syncLayout()"><view class="picker-item">{{ toiletType }}<small>卫生间</small></view></picker><picker :range="['带飘窗','不带飘窗']" @change="bayWindow=['带飘窗','不带飘窗'][$event.detail.value];syncLayout()"><view class="picker-item">{{ bayWindow }}<small>飘窗</small></view></picker></view><view class="layout-preview">已选：{{ form.layout || '请选择房源属性' }}</view><view class="section-title">常用家电与配套</view><checkbox-group class="amenity-grid" @change="amenities=$event.detail.value"><label v-for="option in amenityOptions" :key="option" class="amenity-item"><checkbox :value="option" :checked="amenities.includes(option)" color="#0e8177"/>{{ option }}</label></checkbox-group><view class="field"><text>月租</text><input v-model.number="form.rentMonthly" type="number" placeholder="请输入租金" /></view><view class="field"><text>费用说明</text><input v-model="form.feeText" placeholder="例如：直租无中介费" /></view><view class="field column"><text>文字描述</text><textarea v-model="form.description" placeholder="房屋采光、入住要求等其他说明"></textarea></view><view class="media-grid"><view class="media-box" @click="pick('image')">＋ 图片<small>{{ images.length }}/9</small></view><view class="media-box" @click="pick('video')">＋ 视频<small>{{ videos.length }}/1 · 最长60秒</small></view></view></view><view class="button" @click="save">{{ saving?'保存中...':'保存正式房源' }}</view></view></template>
<style scoped>.hint{color:#4c8880;background:#e5faf5;line-height:1.7}.field{display:flex;align-items:center;padding:24rpx 0;border-bottom:1rpx solid #edf4f1}.field>text{width:150rpx;color:#57857e}.field input{flex:1}.section-title{font-size:30rpx;font-weight:600;color:#174f4a;margin:28rpx 0 16rpx}.picker-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14rpx}.picker-item{padding:20rpx 8rpx;text-align:center;border:1rpx solid #d6eee8;border-radius:16rpx;color:#0e8177;background:#f5fffc}.picker-item small{display:block;font-size:22rpx;color:#78a39d;margin-top:6rpx}.layout-preview{margin:18rpx 0;padding:18rpx;border-radius:14rpx;background:#eefaf6;color:#57857e;font-size:24rpx}.amenity-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20rpx 8rpx;padding:10rpx 0 24rpx}.amenity-item{font-size:26rpx;color:#376d67;display:flex;align-items:center}.column{display:block}.column textarea{width:100%;height:180rpx;margin-top:18rpx}.media-grid{display:flex;gap:18rpx;margin-top:26rpx}.media-box{flex:1;text-align:center;border:2rpx dashed #a9d9d0;border-radius:20rpx;padding:34rpx 10rpx;color:#0e8177}.media-box small{display:block;color:#78a39d;margin-top:12rpx}</style>
